{"step":"trust.preview","exitCode":0,"containsDigest":true,"mutated":false}
{"step":"trust.stale.refused","exitCode":1}
{"step":"trust.command","exitCode":0}
{"step":"trust.audit","originClass":"agent","hashMatches":true,"receipt":{"source":"cli","restoredAt":1795664925957,"previousTrackedWrite":{"originClass":"untrusted"},"reviewedSha256":"[redacted digest]"}}
{"step":"doctor.after","exitCode":1,"excluded":false}
{"step":"automatic.context.after","included":true,"reset":true}
{"step":"unreviewed.bytes.excluded","included":false}
{"step":"tracked.requarantine","originClass":"untrusted","included":false}
